// Exact norm <=8 test for u of centred support seven, all seven entries odd.
// Partition by first supported coordinate, range [first,end).
// Candidate header generated by support7_allodd_verify.py and SHA-checked.
// Integer modulo-8 lower bound then exhaustive centred modulo-16 lifts.
#include <immintrin.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <climits>
#ifdef _OPENMP
#include <omp.h>
#endif
#include "matrix48.h"
using u64=unsigned long long;
static constexpr int sq16[16]={0,1,4,9,16,25,36,49,64,49,36,25,16,9,4,1};
static constexpr int sq8[8]={0,1,4,9,16,9,4,1};
static constexpr int odd[4]={1,3,5,7};
struct V {__m256i a,b;};
static __m256i tbl,mask7;
inline V add(V x,V y){return {_mm256_add_epi8(x.a,y.a),_mm256_add_epi8(x.b,y.b)};}
inline V fromrow(int i,int r){
 alignas(32) uint8_t z[64]={};
 for(int j=0;j<48;j++)z[j]=(uint8_t)(r*A_pad[i][j]);
 return {_mm256_load_si256((const __m256i*)z),_mm256_load_si256((const __m256i*)(z+32))};
}
inline int norm8(__m256i x){
 __m256i r=_mm256_shuffle_epi8(tbl,_mm256_and_si256(x,mask7));
 __m256i s=_mm256_sad_epu8(r,_mm256_setzero_si256());
 return (int)(_mm256_extract_epi64(s,0)+_mm256_extract_epi64(s,1)
              +_mm256_extract_epi64(s,2)+_mm256_extract_epi64(s,3));
}
struct Counts{
 u64 supports=0,patterns=0,passed=0,lifts=0,shorts=0;
 int best=INT_MAX,ids[7]={},u[7]={};
};
static void calc(const int ids[7],Counts&c){
 ++c.supports;
 V terms[7][4];
 for(int i=0;i<7;i++)for(int d=0;d<4;d++)terms[i][d]=fromrow(ids[i],odd[d]);
 V left[64],right[256];int lcost[64],rcost[256];
 for(int p=0;p<64;p++){
  int a=p>>4,b=(p>>2)&3,d=p&3;
  left[p]=add(add(terms[0][a],terms[1][b]),terms[2][d]);
  lcost[p]=odd[a]*odd[a]+sq8[odd[b]]+sq8[odd[d]];
 }
 for(int q=0;q<256;q++){
  int a=q>>6,b=(q>>4)&3,d=(q>>2)&3,e=q&3;
  right[q]=add(add(add(terms[3][a],terms[4][b]),terms[5][d]),terms[6][e]);
  rcost[q]=sq8[odd[a]]+sq8[odd[b]]+sq8[odd[d]]+sq8[odd[e]];
 }
 for(int p=0;p<64;p++)for(int q=0;q<256;q++){
  ++c.patterns;
  int lb=lcost[p]+rcost[q]+41; // seven odd u => exactly 41 odd v
  if(lb>128)continue;
  V v=add(left[p],right[q]);
  lb=lcost[p]+rcost[q]+norm8(v.a);
  if(lb>128)continue;
  lb+=norm8(v.b);
  if(lb>128)continue;
  ++c.passed;
  int dig[7]={p>>4,(p>>2)&3,p&3,q>>6,(q>>4)&3,(q>>2)&3,q&3};
  int u[7]={odd[dig[0]]};
  for(int mask=0;mask<64;mask++){
    for(int i=1;i<7;i++)u[i]=odd[dig[i]]-(((mask>>(i-1))&1)?8:0);
    int n=0;
    for(int i=0;i<7;i++)n+=u[i]*u[i];
    if(n+41>128)continue;
    ++c.lifts;
    for(int j=0;j<48&&n<=128;j++){
      int sum=0;
      for(int i=0;i<7;i++)sum+=u[i]*A_pad[ids[i]][j];
      n+=sq16[((unsigned)sum)&15];
    }
    if(n<=128){
      ++c.shorts;
      if(n<c.best){
        c.best=n;
        memcpy(c.ids,ids,sizeof(c.ids));
        memcpy(c.u,u,sizeof(c.u));
        #pragma omp critical
        {
         printf("WITNESS numerator=%d support=",n);
         for(int i=0;i<7;i++)printf("%d:%d%c",ids[i],u[i],i==6?'\n':',');
         fflush(stdout);
        }
      }
    }
  }
 }
}
static void recurse(int depth,int start,int ids[7],Counts &c){
 if(depth==7){calc(ids,c);return;}
 for(int j=start;j<=48-(7-depth);j++){
  ids[depth]=j;
  recurse(depth+1,j+1,ids,c);
 }
}
int main(int argc,char**argv){
 const int first=argc>1?atoi(argv[1]):0;
 const int end=argc>2?atoi(argv[2]):42;
 if(first<0||end>42||first>=end)return 2;
 alignas(32)uint8_t t[32];
 for(int i=0;i<32;i++)t[i]=sq8[i&7];
 tbl=_mm256_load_si256((const __m256i*)t);mask7=_mm256_set1_epi8(7);
 Counts total;
 #pragma omp parallel
 {
  Counts c;
  #pragma omp for schedule(dynamic,1)
  for(int i=first;i<end;i++){int ids[7]={i};recurse(1,i+1,ids,c);}
  #pragma omp critical
  {
   total.supports+=c.supports;total.patterns+=c.patterns;
   total.passed+=c.passed;total.lifts+=c.lifts;total.shorts+=c.shorts;
   if(c.best<total.best){
    total.best=c.best;
    memcpy(total.ids,c.ids,sizeof(c.ids));
    memcpy(total.u,c.u,sizeof(c.u));
   }
  }
 }
 printf("SUMMARY first=[%d,%d) supports=%llu mod8_patterns=%llu passed_mod8=%llu lifts=%llu short=%llu best_numerator=%d\n",
   first,end,total.supports,total.patterns,total.passed,total.lifts,total.shorts,total.best);
 if(total.shorts){
  printf("WITNESS");
  for(int j=0;j<7;j++)printf(" %d:%d",total.ids[j],total.u[j]);
  printf("\n");
 }
 return total.shorts?3:0;
}
